:root {
  --ui: 'Silkscreen', 'Courier New', monospace;
  --display: 'Press Start 2P', 'Courier New', monospace;
  --btn-w: min(400px, 82vw);
  --white: #fdfdfd;
  --shadow: #3f3f3f;
  --dirt: none;
  --gui-btn: #7d7d7d;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: #000;
  color: var(--white);
  font-family: var(--ui);
  -webkit-font-smoothing: none;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: geometricPrecision;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

button, input { font-family: inherit; }

[hidden] { display: none !important; }

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  background:
    radial-gradient(ellipse at 50% 46%, rgba(0,0,0,0) 42%, rgba(0,0,0,.28) 100%),
    linear-gradient(180deg, rgba(8,12,18,.28) 0%, rgba(0,0,0,0) 22%, rgba(0,0,0,0) 70%, rgba(0,0,0,.45) 100%);
}

/* ============================ boot ============================ */
.boot {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background:
    radial-gradient(circle at 50% 40%, #2c2c2c 0%, #101010 62%, #050505 100%);
  transition: opacity .5s ease;
}
.boot.gone { opacity: 0; pointer-events: none; }
.boot-block {
  width: 78px;
  height: 78px;
  position: relative;
  transform-style: preserve-3d;
  animation: bootspin 3.6s linear infinite;
  margin-bottom: 8px;
}
.boot-face {
  position: absolute;
  width: 78px;
  height: 78px;
  image-rendering: pixelated;
  border: 2px solid #1c1c1c;
  background-color: #6aa84f;
  background-image:
    linear-gradient(180deg, rgba(255,255,255,.22), rgba(0,0,0,.1)),
    repeating-linear-gradient(0deg, rgba(0,0,0,.18) 0 4px, rgba(255,255,255,.06) 4px 8px),
    repeating-linear-gradient(90deg, rgba(0,0,0,.12) 0 4px, rgba(255,255,255,.05) 4px 8px);
}
.boot-face.top { transform: rotateX(90deg) translateZ(39px); background-color: #79b757; }
.boot-face.left { transform: rotateY(-90deg) translateZ(39px); background-color: #5b4a33; }
.boot-face.right { transform: rotateY(0deg) translateZ(39px); }
@keyframes bootspin {
  0% { transform: rotateX(-18deg) rotateY(0deg); }
  100% { transform: rotateX(-18deg) rotateY(360deg); }
}
.boot-text {
  font-family: var(--display);
  font-size: 22px;
  letter-spacing: 2px;
  color: #d8d8d8;
  text-shadow: 3px 3px 0 #4a4a4a, 6px 6px 0 rgba(0,0,0,.5);
}
.boot-sub { font-size: 11px; color: #8f8f8f; }

/* ============================ screens ============================ */
.screen { position: fixed; inset: 0; z-index: 5; }
.screen[hidden] { display: none !important; }

/* ============================ main menu ============================ */
.screen-mainmenu {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(2vh + env(safe-area-inset-top)) 12px calc(4vh + env(safe-area-inset-bottom));
}
.main-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(92vw, 660px);
  margin-top: -1.5vh;
}
.logo-wrap {
  position: relative;
  width: min(100%, 650px);
  filter: drop-shadow(0 10px 16px rgba(0,0,0,.5));
  pointer-events: none;
}
.logo {
  display: block;
  width: 100%;
  height: auto;
  image-rendering: auto;
}
.logo-edition {
  position: absolute;
  right: 6%;
  bottom: 7%;
  font-family: var(--display);
  font-size: clamp(6px, 1vw, 10px);
  color: #ffd85e;
  text-shadow: 2px 2px 0 #5b3d00, -1px -1px 0 #2a1b00;
  letter-spacing: 1px;
  transform: rotate(-2deg);
  opacity: .95;
}
.splash {
  position: absolute;
  left: 62%;
  top: 54%;
  transform: rotate(-17deg);
  transform-origin: left center;
  font-family: var(--display);
  font-size: clamp(8px, 1.25vw, 13px);
  line-height: 1.25;
  color: #ffff3e;
  text-shadow:
    2px 2px 0 #3f3f00,
    -2px 2px 0 #3f3f00,
    2px -2px 0 #3f3f00,
    -2px -2px 0 #3f3f00,
    3px 3px 0 rgba(0,0,0,.55);
  white-space: nowrap;
  animation: splashpulse .55s ease-in-out infinite alternate;
  pointer-events: none;
}
@keyframes splashpulse {
  from { transform: rotate(-17deg) scale(1); }
  to { transform: rotate(-17deg) scale(1.075); }
}
.logo-wrap:hover .splash { animation-duration: .4s; }

.button-column {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: var(--btn-w);
  margin-top: clamp(10px, 2.2vh, 24px);
  z-index: 2;
}

.mc-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  min-height: 44px;
  padding: 6px 14px;
  font-family: var(--ui);
  font-size: 15px;
  font-weight: 400;
  letter-spacing: .4px;
  color: #fff;
  text-align: center;
  text-shadow: 2px 2px 0 var(--shadow);
  background:
    linear-gradient(180deg, rgba(255,255,255,.17) 0%, rgba(255,255,255,0) 26%, rgba(0,0,0,.14) 100%),
    repeating-linear-gradient(90deg, rgba(255,255,255,.035) 0 2px, rgba(0,0,0,.035) 2px 4px),
    repeating-linear-gradient(0deg, rgba(255,255,255,.03) 0 2px, rgba(0,0,0,.03) 2px 4px),
    var(--gui-btn);
  border: 2px solid #000;
  box-shadow:
    inset 2px 2px 0 rgba(255,255,255,.4),
    inset -2px -2px 0 rgba(0,0,0,.42),
    inset 0 0 0 1px rgba(255,255,255,.06);
  cursor: pointer;
  outline: none;
  touch-action: manipulation;
  transition: filter .09s ease, transform .06s ease, box-shadow .09s ease;
  image-rendering: pixelated;
}
.mc-btn:hover { filter: brightness(1.17); }
.mc-btn:active { filter: brightness(.92); transform: translateY(1px); }
.mc-btn:focus-visible {
  box-shadow:
    inset 2px 2px 0 rgba(255,255,255,.4),
    inset -2px -2px 0 rgba(0,0,0,.42),
    0 0 0 2px #fff;
}
.mc-btn:disabled {
  color: #aaa;
  text-shadow: 2px 2px 0 #2c2c2c;
  filter: grayscale(.7) brightness(.8);
  cursor: default;
  transform: none;
}
.mc-btn .music-glyph { color: #ffe45c; text-shadow: 2px 2px 0 #4d3c00; font-size: 16px; }
.mc-btn.music-off .music-glyph { color: #8f8f8f; text-shadow: 2px 2px 0 #333; }

.small-buttons {
  display: flex;
  gap: 8px;
  width: var(--btn-w);
  margin-top: 10px;
}
.mc-btn-small {
  flex: 1 1 0;
  min-height: 34px;
  height: 34px;
  font-size: 10.5px;
  padding: 4px 6px;
  text-shadow: 2px 2px 0 #393939;
  background:
    linear-gradient(180deg, rgba(255,255,255,.14) 0%, rgba(0,0,0,.14) 100%),
    repeating-linear-gradient(90deg, rgba(255,255,255,.03) 0 2px, rgba(0,0,0,.03) 2px 4px),
    #6e6e6e;
}
.mc-btn-small:hover { filter: brightness(1.15); }

.corner {
  position: absolute;
  bottom: calc(6px + env(safe-area-inset-bottom));
  font-size: 12px;
  color: #fff;
  text-shadow: 2px 2px 0 #3f3f3f;
  letter-spacing: .2px;
  pointer-events: none;
  z-index: 3;
}
.corner-left { left: 8px; }
.corner-right { right: 8px; text-align: right; }
.corner .dim { opacity: .65; margin-left: 5px; }

/* ============================ subscreens ============================ */
.subscreen {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: calc(1.4vh + env(safe-area-inset-top)) 14px calc(1.6vh + env(safe-area-inset-bottom));
  overflow: hidden;
}
.dirt-bg {
  position: absolute;
  inset: 0;
  background-color: #5c4a34;
  background-image: var(--dirt);
  background-size: 64px 64px;
  image-rendering: pixelated;
  z-index: -1;
}
.dirt-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 50% 45%, rgba(0,0,0,.4) 0%, rgba(0,0,0,.68) 100%),
    rgba(0,0,0,.18);
}
.screen-title {
  margin: clamp(6px, 1.6vh, 18px) 0 clamp(8px, 1.8vh, 20px);
  font-family: var(--display);
  font-size: clamp(15px, 2.1vw, 24px);
  line-height: 1.5;
  color: #fff;
  text-shadow: 3px 3px 0 #171717;
  text-align: center;
  letter-spacing: 1px;
  flex: 0 0 auto;
}
.sub-body {
  flex: 1 1 auto;
  width: min(94vw, 980px);
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.sub-actions {
  flex: 0 0 auto;
  display: flex;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  width: min(94vw, 980px);
  padding-top: clamp(8px, 1.7vh, 18px);
}
.sub-actions .mc-btn {
  width: auto;
  flex: 0 1 215px;
  min-width: 160px;
  min-height: 42px;
  font-size: 13px;
}
.sub-actions .mc-btn.primary { --gui-btn: #7b8a6a; }

.panel {
  background: rgba(14, 14, 14, .78);
  border: 2px solid #000;
  box-shadow:
    inset 0 0 0 1px rgba(255,255,255,.16),
    0 10px 26px rgba(0,0,0,.42);
}

/* -------- singleplayer layout -------- */
.split {
  display: flex;
  gap: 10px;
  height: min(60vh, 520px);
  width: 100%;
}
.world-panel {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: 10px;
}
.world-summary {
  flex: 0 0 320px;
  display: flex;
  flex-direction: column;
  padding: 16px;
  gap: 14px;
  overflow: hidden;
}
.search-row {
  position: relative;
  display: flex;
  align-items: center;
  margin-bottom: 8px;
}
.search-icon {
  position: absolute;
  left: 10px;
  width: 12px;
  height: 12px;
  border: 2px solid #bdbdbd;
  border-radius: 50%;
  pointer-events: none;
}
.search-icon::after {
  content: '';
  position: absolute;
  width: 2px;
  height: 7px;
  background: #bdbdbd;
  transform: rotate(-45deg);
  left: 10px;
  top: 9px;
}
.search-row .mc-input { padding-left: 30px; width: 100%; }

.mc-input {
  width: 100%;
  min-height: 38px;
  padding: 8px 10px;
  font-family: var(--ui);
  font-size: 12.5px;
  color: #f2f2f2;
  background: rgba(0,0,0,.62);
  border: 2px solid #9a9a9a;
  box-shadow: inset 2px 2px 0 rgba(0,0,0,.55);
  outline: none;
  border-radius: 0;
}
.mc-input::placeholder { color: #7f7f7f; }
.mc-input:focus { border-color: #fff; box-shadow: inset 2px 2px 0 rgba(0,0,0,.55), 0 0 0 1px #fff; }

.scroll-list {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: #8d8d8d #1a1a1a;
}
.scroll-list::-webkit-scrollbar { width: 12px; }
.scroll-list::-webkit-scrollbar-track { background: #151515; border-left: 2px solid #000; }
.scroll-list::-webkit-scrollbar-thumb { background: #8d8d8d; border: 2px solid #000; box-shadow: inset 2px 2px 0 rgba(255,255,255,.35), inset -2px -2px 0 rgba(0,0,0,.4); }

.world-list { padding-right: 4px; }
.world-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 7px 8px;
  border: 2px solid transparent;
  cursor: pointer;
  text-align: left;
  background: transparent;
  color: #fff;
  font-family: var(--ui);
}
.world-row + .world-row { margin-top: 2px; }
.world-row:hover { background: rgba(255,255,255,.08); }
.world-row.selected {
  background: rgba(255,255,255,.16);
  border-color: #c9c9c9;
  box-shadow: inset 0 0 0 1px #000;
}
.world-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  border: 2px solid #000;
  background-size: cover;
  image-rendering: pixelated;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.18);
}
.world-main { min-width: 0; flex: 1 1 auto; }
.world-name {
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 2px 2px 0 #222;
}
.world-meta {
  margin-top: 4px;
  font-size: 9.5px;
  color: #b5b5b5;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.world-meta .warn { color: #ffd45c; }
.world-chevron { color: #8d8d8d; font-family: var(--display); font-size: 10px; padding-right: 2px; }
.empty-note {
  padding: 30px 16px;
  text-align: center;
  font-size: 12px;
  color: #bdbdbd;
  line-height: 1.8;
}
.summary-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255,255,255,.17);
}
.summary-icon {
  width: 60px;
  height: 60px;
  flex: 0 0 60px;
  background-color: #333;
  background-size: cover;
  image-rendering: pixelated;
  border: 2px solid #000;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.2);
}
.summary-name {
  font-size: 15px;
  line-height: 1.4;
  overflow-wrap: anywhere;
  text-shadow: 2px 2px 0 #222;
}
.summary-sub { margin-top: 5px; font-size: 10px; color: #bdbdbd; }
.summary-grid {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 8px 10px;
  font-size: 10px;
  color: #bdbdbd;
  align-items: baseline;
}
.summary-grid b { color: #fff; font-weight: 400; text-align: right; overflow-wrap: anywhere; }
.summary-note {
  margin-top: auto;
  font-size: 9.5px;
  line-height: 1.9;
  color: #9e9e9e;
  border-top: 1px solid rgba(255,255,255,.12);
  padding-top: 10px;
}

/* -------- create world -------- */
.form-panel {
  width: min(94vw, 560px);
  padding: clamp(14px, 2.2vh, 24px);
  display: flex;
  flex-direction: column;
  gap: clamp(10px, 1.6vh, 16px);
  max-height: 64vh;
  overflow-y: auto;
}
.field { display: flex; flex-direction: column; gap: 6px; font-size: 11.5px; color: #d2d2d2; }
.field .mc-input { font-size: 13px; }
.toggle-btn { width: 170px; align-self: flex-start; min-height: 36px; font-size: 11.5px; }
.toggle-btn[data-on="true"] { --gui-btn: #6f8064; }
.create-preview {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px;
  background: rgba(0,0,0,.38);
  border: 2px solid #000;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.1);
  margin-top: 2px;
}
.preview-icon {
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  background-size: cover;
  image-rendering: pixelated;
  border: 2px solid #000;
}
.preview-text { font-size: 10px; color: #b9b9b9; line-height: 1.9; }

/* -------- multiplayer -------- */
.server-panel {
  width: 100%;
  height: min(58vh, 500px);
  padding: 10px;
  display: flex;
  flex-direction: column;
}
.server-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 10px;
  border: 2px solid transparent;
  cursor: pointer;
  text-align: left;
  background: transparent;
  color: #fff;
  font-family: var(--ui);
  width: 100%;
}
.server-row:hover { background: rgba(255,255,255,.07); }
.server-row.selected {
  background: rgba(255,255,255,.15);
  border-color: #cfcfcf;
  box-shadow: inset 0 0 0 1px #000;
}
.server-icon {
  width: 42px; height: 42px; flex: 0 0 42px;
  border: 2px solid #000;
  image-rendering: pixelated;
  background-size: cover;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.15);
}
.server-main { flex: 1 1 auto; min-width: 0; }
.server-name { font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-shadow: 2px 2px 0 #222; }
.server-motd { margin-top: 4px; font-size: 9.5px; color: #bdbdbd; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.server-side { display: flex; align-items: center; gap: 12px; flex: 0 0 auto; }
.server-players { font-size: 10px; color: #bdbdbd; text-align: right; line-height: 1.6; }
.ping { display: flex; align-items: flex-end; gap: 2px; height: 16px; width: 24px; }
.ping i { display: block; width: 4px; background: #4c4c4c; box-shadow: inset 0 0 0 1px rgba(0,0,0,.4); }
.ping i:nth-child(1) { height: 6px; }
.ping i:nth-child(2) { height: 10px; }
.ping i:nth-child(3) { height: 14px; }
.ping.p1 i:nth-child(1) { background: #e25555; }
.ping.p2 i:nth-child(-n+2) { background: #e0b34a; }
.ping.p3 i { background: #61c554; }
.ping.p4 i { background: #3fae3f; }
.ping.pinging i { animation: pingflash .6s infinite alternate; }
.ping.pinging i { background: #8f8f8f; }
@keyframes pingflash { from { opacity: .25; } to { opacity: 1; } }
.dot { width: 7px; height: 7px; display: inline-block; border-radius: 50%; margin-right: 6px; box-shadow: 0 0 0 1px rgba(0,0,0,.4); }
.dot.online { background: #57c955; }
.dot.offline { background: #666; }
.modal {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0,0,0,.6);
  backdrop-filter: blur(2px);
}
.modal-panel {
  width: min(92vw, 480px);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  background: #171717;
}
.modal-panel h2 {
  margin: 0 0 4px;
  font-family: var(--display);
  font-size: 13px;
  line-height: 1.6;
  text-shadow: 2px 2px 0 #000;
}
.modal-actions { display: flex; gap: 8px; justify-content: flex-end; margin-top: 4px; }
.modal-actions .mc-btn { width: auto; min-width: 130px; min-height: 38px; font-size: 12px; }

/* -------- realms -------- */
.realm-panel {
  width: min(94vw, 620px);
  padding: 0 0 18px;
  overflow: hidden;
}
.realm-banner {
  position: relative;
  padding: 18px 22px;
  background:
    linear-gradient(110deg, #1f3c5a 0%, #215a5b 48%, #2d6b46 100%);
  border-bottom: 2px solid #000;
  overflow: hidden;
}
.realm-banner::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    repeating-linear-gradient(0deg, rgba(255,255,255,.06) 0 3px, transparent 3px 6px),
    repeating-linear-gradient(90deg, rgba(0,0,0,.1) 0 3px, transparent 3px 6px);
  opacity: .6;
}
.realm-logo {
  font-family: var(--display);
  font-size: clamp(20px, 4vw, 34px);
  letter-spacing: 2px;
  color: #fff;
  text-shadow: 3px 3px 0 #10263c;
  position: relative; z-index: 1;
}
.realm-logo-sub {
  font-family: var(--display);
  font-size: 8px;
  letter-spacing: 4px;
  color: #bfe8d2;
  margin-top: 8px;
  position: relative; z-index: 1;
}
.realm-card {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 18px;
  padding: 12px;
  background: rgba(255,255,255,.06);
  border: 2px solid #000;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.16);
}
.realm-icon {
  width: 58px; height: 58px; flex: 0 0 58px;
  border: 2px solid #000;
  image-rendering: pixelated;
  background-color: #2f5b46;
  background-image:
    linear-gradient(180deg, rgba(255,255,255,.18), rgba(0,0,0,.25)),
    repeating-linear-gradient(45deg, rgba(255,255,255,.1) 0 4px, transparent 4px 8px);
}
.realm-info { flex: 1 1 auto; min-width: 0; }
.realm-name { font-size: 13px; text-shadow: 2px 2px 0 #222; }
.realm-sub { font-size: 9.5px; color: #bdbdbd; margin-top: 5px; }
.realm-players { font-size: 9.5px; color: #d8d8d8; margin-top: 7px; }
.realm-status {
  font-size: 9px;
  color: #ffdf6b;
  border: 2px solid #000;
  background: rgba(90, 72, 18, .65);
  padding: 6px 8px;
  white-space: nowrap;
}
.realm-note { margin: 0 18px; font-size: 9.5px; color: #a3a3a3; line-height: 1.9; }

/* -------- options / accessibility -------- */
.options-panel {
  width: min(94vw, 680px);
  max-height: 64vh;
  overflow-y: auto;
  padding: 8px 20px 16px;
}
.opt-section {
  margin: 16px 0 4px;
  font-family: var(--display);
  font-size: 9.5px;
  color: #ffdf6b;
  letter-spacing: 1px;
  text-shadow: 2px 2px 0 #2a2100;
}
.opt-section:first-child { margin-top: 8px; }
.opt-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 48px;
  font-size: 12px;
  border-bottom: 1px solid rgba(255,255,255,.09);
}
.opt-row > span:first-child { color: #e8e8e8; text-shadow: 1px 1px 0 #222; }
.slider-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
  width: min(330px, 52vw);
  flex: 0 0 auto;
}
.slider-val {
  width: 42px;
  text-align: right;
  font-size: 11px;
  color: #ffdf6b;
  text-shadow: 1px 1px 0 #333;
}
.mc-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 34px;
  margin: 0;
  background: transparent;
  cursor: pointer;
}
.mc-slider::-webkit-slider-runnable-track {
  height: 8px;
  background: #0b0b0b;
  border: 2px solid #000;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.24);
}
.mc-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 40px;
  height: 28px;
  margin-top: -12px;
  background:
    linear-gradient(180deg, rgba(255,255,255,.2) 0%, rgba(0,0,0,.16) 100%),
    repeating-linear-gradient(90deg, rgba(255,255,255,.04) 0 2px, rgba(0,0,0,.04) 2px 4px),
    #858585;
  border: 2px solid #000;
  box-shadow: inset 2px 2px 0 rgba(255,255,255,.36), inset -2px -2px 0 rgba(0,0,0,.4);
}
.mc-slider::-moz-range-track {
  height: 8px; background: #0b0b0b; border: 2px solid #000;
}
.mc-slider::-moz-range-thumb {
  width: 40px; height: 28px; border-radius: 0;
  background: #858585; border: 2px solid #000;
}
.mc-slider:focus-visible { outline: 2px solid #fff; outline-offset: 3px; }
.opt-row .toggle-btn { width: 140px; min-height: 34px; font-size: 10.5px; align-self: center; }
.access-note { margin: 18px 0 4px; font-size: 9.5px; color: #a9a9a9; line-height: 1.9; }

/* -------- language -------- */
.list-panel {
  width: min(94vw, 540px);
  max-height: 62vh;
  overflow-y: auto;
  padding: 8px;
}
.lang-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 10px;
  background: transparent;
  border: 2px solid transparent;
  color: #fff;
  font-family: var(--ui);
  font-size: 12px;
  cursor: pointer;
  text-align: left;
}
.lang-row:hover { background: rgba(255,255,255,.08); }
.lang-row.selected { background: rgba(255,255,255,.13); border-color: #bdbdbd; box-shadow: inset 0 0 0 1px #000; }
.lang-flag {
  width: 28px; height: 19px; flex: 0 0 28px;
  image-rendering: pixelated;
  border: 2px solid #000;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.25);
}
.lang-code { margin-left: auto; font-size: 9px; color: #9c9c9c; }
.lang-check { width: 18px; text-align: center; color: #7fe06a; font-family: var(--display); font-size: 10px; }

/* -------- pause -------- */
.pause-screen {
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(180deg, rgba(4,8,14,.62), rgba(4,8,14,.78));
  backdrop-filter: blur(2px) saturate(.85);
  z-index: 25;
  padding: 20px;
}
.pause-inner { display: flex; flex-direction: column; align-items: center; width: min(92vw, 460px); }
.pause-title {
  font-family: var(--display);
  font-size: clamp(16px, 2.4vw, 24px);
  text-shadow: 3px 3px 0 #000;
  margin-bottom: 10px;
}
.pause-world { font-size: 11px; color: #bdbdbd; margin-bottom: 26px; text-shadow: 2px 2px 0 #000; }
.pause-inner .button-column { width: min(100%, 400px); gap: 10px; }
.pause-inner .mc-btn { min-height: 44px; }

/* -------- loading -------- */
.loading-screen {
  z-index: 40;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.loading-inner {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  margin-top: -8vh;
  width: min(90vw, 460px);
}
.loading-label {
  font-family: var(--display);
  font-size: clamp(12px, 1.7vw, 16px);
  text-shadow: 2px 2px 0 #000;
  text-align: center;
  line-height: 1.7;
}
.loading-bar {
  position: relative;
  width: 100%;
  height: 14px;
  border: 2px solid #fff;
  background: #1c1c1c;
  box-shadow: 0 0 0 2px #000, inset 0 0 0 1px rgba(0,0,0,.6);
  overflow: hidden;
}
.loading-fill {
  height: 100%;
  width: 0%;
  background: linear-gradient(180deg, #8fdd67 0%, #58a83c 46%, #3f7d2e 100%);
  box-shadow: inset 0 2px 0 rgba(255,255,255,.35), inset 0 -2px 0 rgba(0,0,0,.3);
  transition: width .15s linear;
}
.loading-sheen {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 0%, rgba(255,255,255,.22) 50%, transparent 100%);
  transform: translateX(-100%);
  animation: sheen 1.8s linear infinite;
}
@keyframes sheen { to { transform: translateX(100%); } }
.loading-sub { font-size: 10.5px; color: #b9b9b9; text-shadow: 2px 2px 0 #222; text-align: center; }
.loading-tip {
  position: absolute;
  left: 50%;
  bottom: calc(4vh + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  z-index: 2;
  width: min(92vw, 760px);
  font-size: 10px;
  line-height: 1.9;
  color: #d7d7d7;
  text-shadow: 2px 2px 0 #222;
  text-align: center;
}
.loading-tip b { color: #ffdf6b; }

/* -------- quit -------- */
.quit-screen {
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 38%, #251b14 0%, #0c0a08 55%, #000 100%);
  z-index: 50;
}
.quit-inner { display: flex; flex-direction: column; align-items: center; gap: 16px; text-align: center; padding: 20px; }
.quit-title {
  font-family: var(--display);
  font-size: clamp(18px, 3.4vw, 32px);
  color: #ffe066;
  text-shadow: 3px 3px 0 #5a3c00, 6px 6px 0 rgba(0,0,0,.6);
  line-height: 1.6;
}
.quit-sub { font-size: 12px; color: #c9c9c9; text-shadow: 2px 2px 0 #222; }
.quit-heart {
  font-size: 34px;
  color: #d84444;
  text-shadow: 3px 3px 0 #3d0b0b;
  margin: 6px 0 10px;
}
.quit-heart::before { content: '♥'; }
.quit-inner .mc-btn { width: min(86vw, 320px); }

/* ============================ HUD ============================ */
.hud { position: fixed; inset: 0; z-index: 20; pointer-events: none; }
.crosshair {
  position: absolute;
  left: 50%; top: 50%;
  width: 22px; height: 22px;
  transform: translate(-50%, -50%);
  mix-blend-mode: difference;
  opacity: .9;
}
.crosshair::before, .crosshair::after { content: ''; position: absolute; background: #fff; }
.crosshair::before { left: 10px; top: 0; width: 2px; height: 22px; }
.crosshair::after { top: 10px; left: 0; height: 2px; width: 22px; }
.hotbar {
  position: absolute;
  left: 50%;
  bottom: calc(12px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: flex;
  gap: 0;
  padding: 3px;
  background: rgba(12, 12, 12, .45);
  border: 2px solid #000;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.14), 0 4px 14px rgba(0,0,0,.4);
  pointer-events: none;
}
.hot-slot {
  position: relative;
  width: 50px;
  height: 50px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid rgba(150,150,150,.55);
  background: rgba(120,120,120,.22);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.35);
}
.hot-slot + .hot-slot { margin-left: -2px; }
.hot-slot.selected {
  border-color: #fff;
  box-shadow: inset 0 0 0 2px #000, 0 0 0 2px #fff;
  z-index: 2;
  background: rgba(200,200,200,.24);
}
.hot-slot img { width: 36px; height: 36px; image-rendering: pixelated; filter: drop-shadow(2px 3px 1px rgba(0,0,0,.5)); }
.hot-num {
  position: absolute;
  top: 2px; left: 4px;
  font-size: 8px;
  color: #e2e2e2;
  text-shadow: 1px 1px 0 #000;
  opacity: .75;
}
.block-label {
  position: absolute;
  left: 50%;
  bottom: calc(76px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  font-size: 13px;
  color: #fff;
  text-shadow: 2px 2px 0 #000;
  opacity: 0;
  transition: opacity .35s ease;
  white-space: nowrap;
}
.block-label.show { opacity: 1; }
.debug-panel {
  position: absolute;
  left: 8px; top: 8px;
  padding: 6px 8px;
  font-size: 10px;
  line-height: 1.7;
  color: #fff;
  text-shadow: 1px 1px 0 #000;
  background: rgba(0,0,0,.35);
  white-space: pre;
}
.game-hint {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: radial-gradient(ellipse at center, rgba(0,0,0,.32), rgba(0,0,0,.62));
  pointer-events: none;
  z-index: 4;
}
.hint-name {
  font-family: var(--display);
  font-size: clamp(16px, 2.4vw, 26px);
  color: #fff;
  text-shadow: 3px 3px 0 #000;
  text-align: center;
  padding: 0 20px;
}
.hint-play {
  font-size: 12px;
  color: #ffe066;
  text-shadow: 2px 2px 0 #000;
  animation: hintpulse 1.1s ease-in-out infinite alternate;
}
@keyframes hintpulse { from { opacity: .55; } to { opacity: 1; } }
.hint-controls {
  font-size: 10px;
  color: #cfcfcf;
  text-shadow: 2px 2px 0 #000;
  max-width: 90vw;
  text-align: center;
  line-height: 1.9;
}
.fps-note {
  position: absolute;
  right: 8px; top: 8px;
  font-size: 9px;
  color: #fff;
  text-shadow: 1px 1px 0 #000;
  opacity: .55;
}
.touch-controls { position: absolute; inset: 0; pointer-events: none; }
.joystick {
  position: absolute;
  left: calc(18px + env(safe-area-inset-left));
  bottom: calc(20px + env(safe-area-inset-bottom));
  width: 118px;
  height: 118px;
  border-radius: 50%;
  background: rgba(255,255,255,.08);
  border: 2px solid rgba(255,255,255,.32);
  box-shadow: inset 0 0 0 2px rgba(0,0,0,.3);
  pointer-events: auto;
  touch-action: none;
}
.joystick-knob {
  position: absolute;
  left: 50%; top: 50%;
  width: 50px; height: 50px;
  margin: -25px 0 0 -25px;
  border-radius: 50%;
  background: rgba(255,255,255,.32);
  border: 2px solid rgba(255,255,255,.55);
  box-shadow: 0 2px 8px rgba(0,0,0,.4);
}
.touch-buttons {
  position: absolute;
  right: calc(16px + env(safe-area-inset-right));
  bottom: calc(24px + env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: 64px 64px;
  grid-template-rows: 64px 64px;
  gap: 10px;
  pointer-events: auto;
}
.touch-btn {
  width: 64px; height: 64px;
  border-radius: 50%;
  border: 2px solid rgba(255,255,255,.45);
  background: rgba(20,20,20,.42);
  color: #fff;
  font-family: var(--ui);
  font-size: 22px;
  text-shadow: 2px 2px 0 #000;
  display: flex;
  align-items: center;
  justify-content: center;
  touch-action: none;
}
.touch-btn.jump { grid-column: 2; grid-row: 1; }
.touch-btn.place { grid-column: 1; grid-row: 2; font-size: 26px; }
.touch-btn.break { grid-column: 2; grid-row: 2; }
.touch-btn:active { background: rgba(255,255,255,.22); }
.touch-pause {
  position: absolute;
  right: calc(12px + env(safe-area-inset-right));
  top: calc(12px + env(safe-area-inset-top));
  width: 44px; height: 44px;
  border: 2px solid rgba(255,255,255,.4);
  background: rgba(0,0,0,.35);
  color: #fff;
  font-family: var(--ui);
  font-size: 13px;
  pointer-events: auto;
}

/* ============================ toasts ============================ */
.toasts {
  position: fixed;
  top: calc(14px + env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%);
  z-index: 60;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  pointer-events: none;
  width: min(92vw, 460px);
}
.toast {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 10px 14px;
  background: #212121;
  border: 2px solid #000;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.35), 0 6px 18px rgba(0,0,0,.5);
  animation: toastin .28s ease-out both;
  overflow: hidden;
}
.toast.out { animation: toastout .4s ease-in both; }
.toast-icon { width: 34px; height: 34px; flex: 0 0 34px; image-rendering: pixelated; background-size: cover; border: 2px solid #000; }
.toast-title {
  font-family: var(--display);
  font-size: 9px;
  color: #ffe066;
  text-shadow: 2px 2px 0 #3d2d00;
  margin-bottom: 6px;
  line-height: 1.4;
}
.toast-desc { font-size: 10px; color: #eaeaea; line-height: 1.5; }
.toast.plain { background: rgba(20,20,20,.92); }
.toast.plain .toast-title { color: #fff; }
.toast.error { background: #4a1717; box-shadow: inset 0 0 0 1px #ff7b7b; }
@keyframes toastin { from { opacity: 0; transform: translateY(-12px); } to { opacity: 1; transform: translateY(0); } }
@keyframes toastout { to { opacity: 0; transform: translateY(-10px); } }

/* ============================ fade ============================ */
.fade {
  position: fixed;
  inset: 0;
  z-index: 70;
  background: #000;
  opacity: 0;
  pointer-events: none;
  transition: opacity .3s ease;
}
.fade.active { opacity: 1; pointer-events: all; }

/* ============================ accessibility modes ============================ */
body.high-contrast .mc-btn {
  color: #fff;
  text-shadow: 2px 2px 0 #000, 0 0 3px #000;
  border-color: #000;
