  grd.addColorStop(0, `hsl(${hue}, 46%, 38%)`);
  grd.addColorStop(1, `hsl(${hue + 30}, 42%, 16%)`);
  g.fillStyle = grd; g.fillRect(0, 0, 64, 64);
  g.fillStyle = 'rgba(0,0,0,.28)';
  for (let y = 0; y < 64; y += 8) g.fillRect(0, y, 64, 1);
