437: /* ============================================================
438:    Noise
439:    ============================================================ */
440: function hash2i(x, y, seed) {
441:   let h = Math.imul(x, 374761393) ^ Math.imul(y, 668265263) ^ Math.imul(seed, 1442695041);
442:   h = Math.imul(h ^ (h >>> 13), 1274126177);
443:   return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
444: }
445: function smooth(t) { return t * t * (3 - 2 * t); }
446: function noise2(x, y, seed) {
447:   const xi = Math.floor(x), yi = Math.floor(y);
448:   const xf = x - xi, yf = y - yi;
449:   const u = smooth(xf), v = smooth(yf);
450:   const a = hash2i(xi, yi, seed), b = hash2i(xi + 1, yi, seed);
451:   const c = hash2i(xi, yi + 1, seed), d = hash2i(xi + 1, yi + 1, seed);
452:   return (a + (b - a) * u) * (1 - v) + (c + (d - c) * u) * v;
453: }
